class Solution {
public:
    int minimumCardPickup(std::vector<int>& cards) {
        std::unordered_map<int, int> last_seen;
        int min_len = 1e9;
        for (int i = 0; i < (int)cards.size(); ++i) {
            if (last_seen.count(cards[i])) {
                min_len = std::min(min_len, i - last_seen[cards[i]] + 1);
            }
            last_seen[cards[i]] = i;
        }
        return min_len == 1e9 ? -1 : min_len;
    }
};

class Solution {
    public int minimumCardPickup(int[] cards) {
        java.util.Map<Integer, Integer> lastSeen = new java.util.HashMap<>();
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < cards.length; i++) {
            if (lastSeen.containsKey(cards[i])) {
                minLen = Math.min(minLen, i - lastSeen.get(cards[i]) + 1);
            }
            lastSeen.put(cards[i], i);
        }
        return minLen == Integer.MAX_VALUE ? -1 : minLen;
    }
}

var minimumCardPickup = function(cards) {
    const lastSeen = new Map();
    let minLen = Infinity;
    for (let i = 0; i < cards.length; i++) {
        if (lastSeen.has(cards[i])) {
            minLen = Math.min(minLen, i - lastSeen.get(cards[i]) + 1);
        }
        lastSeen.set(cards[i], i);
    }
    return minLen === Infinity ? -1 : minLen;
};
